using System;using System.IO;using System.Collections.Generic;using CircuitoStudio;
class CableSelectionTests{static int n;static void Check(bool v){n++;if(!v)throw new Exception("Check "+n);}static void Reject(string f,string s){File.WriteAllText(f,s);try{CableSelection.ImportCsv(f);}catch(InvalidDataException){n++;return;}throw new Exception("Invalid accepted");}static void Main(){string dir=Path.Combine(Path.GetTempPath(),"cable-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string f=Path.Combine(dir,"a.csv");string h=CableSelection.Header+"\n";CableSelection.ExportCsv(new List<CableOption>(),f);Check(CableSelection.ImportCsv(f).Count==0);var o=new CableOption{Name="Teste;\"X\"\nlinha",Material="Cu",Insulation="PVC",Installation="B1",SectionMm2=10,IzA=60,ResistanceOhmKm=2.37,ReactanceOhmKm=0,Reference="Fonte explicitamente informada"};CableSelection.ExportCsv(new List<CableOption>{o},f);Check(CableSelection.ImportCsv(f)[0].Name==o.Name);var p=new Project();p.Source=new SourceSettings();var c=new Circuit{PowerKw=2.2,PowerFactor=1,Voltage=220,LengthM=100,BreakerA=20};c.Cable=new CableData{InstallationMethod="B1"};c.Protection=new ProtectionData{ConventionalTripA=25,LetThroughA2s=10000,DisconnectSeconds=.1};var board=new Board{Id="Q1",Voltage=380};board.Circuits.Add(c);p.Boards.Add(board);var e=CableSelection.Evaluate(p,c,o);Check(Math.Abs(e.Ib-10)<1e-9);Check(Math.Abs(e.Drop-2.1545454545)<1e-8);Check(e.Status=="Atende verificações locais");var large=new CableOption{Name="Grande",Material="Copper",Insulation="PVC",Installation="B1",SectionMm2=20,IzA=80,ResistanceOhmKm=1.185,ReactanceOhmKm=0,Reference="Teste"};Check(CableSelection.Evaluate(p,c,large).Drop<e.Drop);c.BreakerA=0;Check(CableSelection.Evaluate(p,c,o).Status=="Dados incompletos");c.Cable.InstallationMethod="B1";c.PowerKw=0;c.ReactiveKvarOverride=-10;c.Voltage=380;c.Phases=PhaseMode.Trifasico;var ce=CableSelection.Evaluate(p,c,o);Check(Math.Abs(ce.Ib-15.19342814)<1e-7);var xo=new CableOption{Name="X",Material="Cu",Insulation="PVC",Installation="B1",SectionMm2=10,IzA=60,ResistanceOhmKm=2.37,ReactanceOhmKm=.1,Reference="Teste"};Check(CableSelection.Evaluate(p,c,xo).Drop<0);xo.ReactanceOhmKm=100;Check(CableSelection.Evaluate(p,c,xo).Status=="Não atende");var child=new Board{Id="Q2",Voltage=380};child.Circuits.Add(new Circuit{Id="L2",PowerKw=6,PowerFactor=1,Voltage=380,Phases=PhaseMode.Trifasico});p.Boards.Add(child);c.ChildBoardId="Q2";c.PowerKw=99;Check(Math.Abs(CableSelection.Evaluate(p,c,o).Ib-6000/(Math.Sqrt(3)*380))<1e-9);c.Cable.InstallationMethod="A1";Check(!CableSelection.Matches(o,c));Reject(f,h+"A;Cu;PVC;B1;10;60;0;0;\n");Reject(f,h+"A;Cu;PVC;B1;0;60;0;0;Ref\n");Reject(f,h+"A;Cu;PVC;B1;10;NaN;0;0;Ref\n");Reject(f,h+"A;Cu;PVC;B1;10;60;-1;0;Ref\n");Reject(f,h+"A;Cu;PVC;B1;10;60;1.234,5;0;Ref\n");Reject(f,h+"A;Cu;PVC;B1;10;60;0;0;Ref\nA;Cu;PVC;B1;10;60;0;0;Ref\n");Reject(f,h+"A;\"unclosed");Reject(f,h+"A;Cu;PVC;B1;10;60;0;0;\"Ref\"bad\n");Reject(f,h+"A;Cu;PVC\n");Console.WriteLine("PASS: "+n+" cable assertions");}finally{Directory.Delete(dir,true);}}}
